/**
 * Simple HTML to Canvas converter
 * Converts DOM elements to canvas for image export
 */
(function(window) {
    'use strict';

    function html2canvas(element, options) {
        options = options || {};
        var scale = options.scale || 2;
        var backgroundColor = options.backgroundColor || '#ffffff';

        return new Promise(function(resolve, reject) {
            try {
                // Get element dimensions
                var rect = element.getBoundingClientRect();
                var width = rect.width;
                var height = rect.height;

                // Create canvas
                var canvas = document.createElement('canvas');
                canvas.width = width * scale;
                canvas.height = height * scale;
                var ctx = canvas.getContext('2d');

                // Scale context
                ctx.scale(scale, scale);

                // Fill background
                ctx.fillStyle = backgroundColor;
                ctx.fillRect(0, 0, width, height);

                // Clone the element to avoid modifying the original
                var clone = element.cloneNode(true);
                clone.style.position = 'absolute';
                clone.style.left = '-9999px';
                document.body.appendChild(clone);

                // Use html2canvas rendering
                renderElement(ctx, clone, 0, 0);

                // Remove clone
                document.body.removeChild(clone);

                resolve(canvas);
            } catch (error) {
                reject(error);
            }
        });
    }

    function renderElement(ctx, element, offsetX, offsetY) {
        // Get computed styles
        var styles = window.getComputedStyle(element);
        var rect = element.getBoundingClientRect();

        // Skip if display none or visibility hidden
        if (styles.display === 'none' || styles.visibility === 'hidden') {
            return;
        }

        // Save context
        ctx.save();

        // Render background
        if (styles.backgroundColor && styles.backgroundColor !== 'rgba(0, 0, 0, 0)' && styles.backgroundColor !== 'transparent') {
            ctx.fillStyle = styles.backgroundColor;
            ctx.fillRect(offsetX, offsetY, rect.width, rect.height);
        }

        // Render background gradient if present
        var bgImage = styles.backgroundImage;
        if (bgImage && bgImage !== 'none') {
            renderBackgroundImage(ctx, element, offsetX, offsetY, styles);
        }

        // Render border
        if (styles.borderWidth && parseFloat(styles.borderWidth) > 0) {
            var borderWidth = parseFloat(styles.borderWidth);
            var borderColor = styles.borderColor;
            var borderRadius = parseFloat(styles.borderRadius) || 0;

            ctx.strokeStyle = borderColor;
            ctx.lineWidth = borderWidth;

            if (borderRadius > 0) {
                roundRect(ctx, offsetX, offsetY, rect.width, rect.height, borderRadius);
                ctx.stroke();
            } else {
                ctx.strokeRect(offsetX + borderWidth/2, offsetY + borderWidth/2,
                             rect.width - borderWidth, rect.height - borderWidth);
            }
        }

        // Render text content
        if (element.nodeType === Node.TEXT_NODE) {
            var text = element.textContent.trim();
            if (text) {
                var parent = element.parentElement;
                var parentStyles = window.getComputedStyle(parent);
                renderText(ctx, text, offsetX, offsetY, parentStyles);
            }
        }

        // Render element text
        if (element.textContent && !element.children.length) {
            renderText(ctx, element.textContent, offsetX, offsetY, styles);
        }

        // Render images
        if (element.tagName === 'IMG') {
            try {
                ctx.drawImage(element, offsetX, offsetY, rect.width, rect.height);
            } catch (e) {
                console.warn('Could not draw image:', e);
            }
        }

        // Render canvas elements (like QR codes)
        if (element.tagName === 'CANVAS') {
            try {
                ctx.drawImage(element, offsetX, offsetY, rect.width, rect.height);
            } catch (e) {
                console.warn('Could not draw canvas:', e);
            }
        }

        // Render children
        var children = element.children;
        for (var i = 0; i < children.length; i++) {
            var child = children[i];
            var childRect = child.getBoundingClientRect();
            var childOffsetX = childRect.left - rect.left + offsetX;
            var childOffsetY = childRect.top - rect.top + offsetY;
            renderElement(ctx, child, childOffsetX, childOffsetY);
        }

        // Restore context
        ctx.restore();
    }

    function renderBackgroundImage(ctx, element, offsetX, offsetY, styles) {
        var bgImage = styles.backgroundImage;

        // Handle linear gradients
        if (bgImage.indexOf('linear-gradient') !== -1) {
            var rect = element.getBoundingClientRect();
            var gradient;

            // Parse gradient direction
            if (bgImage.indexOf('135deg') !== -1) {
                gradient = ctx.createLinearGradient(offsetX, offsetY,
                                                    offsetX + rect.width, offsetY + rect.height);
            } else {
                gradient = ctx.createLinearGradient(offsetX, offsetY,
                                                    offsetX + rect.width, offsetY);
            }

            // Extract colors from gradient string
            var colors = extractGradientColors(bgImage);
            if (colors.length >= 2) {
                gradient.addColorStop(0, colors[0]);
                gradient.addColorStop(1, colors[1]);
            }

            ctx.fillStyle = gradient;

            // Handle border radius
            var borderRadius = parseFloat(styles.borderRadius) || 0;
            if (borderRadius > 0) {
                roundRect(ctx, offsetX, offsetY, rect.width, rect.height, borderRadius);
                ctx.fill();
            } else {
                ctx.fillRect(offsetX, offsetY, rect.width, rect.height);
            }
        }
    }

    function extractGradientColors(gradientString) {
        // Simple color extraction from gradient string
        var colors = [];
        var matches = gradientString.match(/(#[0-9a-fA-F]{3,6}|rgb\([^)]+\)|rgba\([^)]+\))/g);
        if (matches) {
            colors = matches;
        }
        return colors;
    }

    function renderText(ctx, text, x, y, styles) {
        ctx.fillStyle = styles.color || '#000000';
        ctx.font = styles.fontSize + ' ' + styles.fontFamily;
        ctx.textAlign = styles.textAlign || 'left';
        ctx.textBaseline = 'top';

        var fontSize = parseFloat(styles.fontSize);
        ctx.fillText(text.trim(), x, y + fontSize * 0.2);
    }

    function roundRect(ctx, x, y, width, height, radius) {
        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.lineTo(x + width - radius, y);
        ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
        ctx.lineTo(x + width, y + height - radius);
        ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
        ctx.lineTo(x + radius, y + height);
        ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
        ctx.lineTo(x, y + radius);
        ctx.quadraticCurveTo(x, y, x + radius, y);
        ctx.closePath();
    }

    // Export to global scope
    window.html2canvas = html2canvas;

})(window);
